+	}
+	if !prepared.Enabled {
+		return result, nil
+	}
+	state, err := service.PerformanceStatus(projectRef, sprintRef)
+	if err != nil {
+		if errors.Is(err, os.ErrNotExist) {
+			result.Fresh = true
+			result.NextAction = displaySafe(prepared.NextAction)
+			return result, nil
+		}
+		return result, err
+	}
+	result.Phase, result.Fresh, result.FreshnessReasons, result.PerformanceAttemptID, result.OperationRunID, result.OperationalAttemptID, result.FencingGeneration, result.Outcome = string(state.Phase), state.Fresh, qaDisplayStrings(state.FreshnessReasons), state.AttemptID, state.Correlation.RunID, state.Correlation.OperationalAttemptID, state.Correlation.FencingGeneration, string(state.Outcome)
+	result.Consumed, result.Limits, result.Blocker, result.NextAction = state.Counters, state.Limits, displaySafe(state.Blocker), displaySafe(state.NextAction)
+	if state.Result != nil {
+		result.Result = performanceArtifactProjection(*state.Result)
+		terminal, resultErr := service.PerformanceCurrentResult(projectRef, sprintRef)
+		if resultErr != nil {
+			return result, resultErr
+		}
+		result.Targets = result.Targets[:0]
+		for _, target := range terminal.TargetResults {
+			projected := performanceTargetProjection(target.Target)
+			baseline, final := target.BaselineQualification, target.FinalQualification
+			projected.BaselineQualification, projected.FinalQualification = &baseline, &final
+			projected.Comparison, projected.Outcome = target.Comparison.ComparedValue, string(target.Comparison.Outcome)
+			result.Targets = append(result.Targets, projected)
+		}
+	}
+	return result, nil
+}
+
+func performanceTargetProjection(target sprint.PerformanceTarget) PerformanceTargetSummary {
+	return PerformanceTargetSummary{ID: target.ID, Scenario: displaySafe(target.Scenario), Metric: displaySafe(target.Metric), Comparator: string(target.Comparator), Value: target.Value, Unit: string(target.Unit), Gate: string(target.Gate), Samples: target.Samples, Basis: string(target.Basis)}
+}
+
+func performanceArtifactProjection(ref sprint.PerformanceArtifactRef) *PerformanceArtifactSummary {
+	if ref.Path == "" || ref.Digest == "" {
+		return nil
+	}
+	return &PerformanceArtifactSummary{Path: ref.Path, Digest: ref.Digest}
 }

